contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address from, address[] memory tos, uint v) public payable {
        require(tos.length <= 2);
        uint balBefore = address(c).balance;
        bool reverted;
        bool ret;
        if (tos.length == 0) {
            try c.transfer(from, address(this), tos, v) returns (bool r) {
                reverted = false;
                ret = r;
            } catch {
                reverted = true;
                ret = false;
            }
            assert(reverted && !ret);
        } else {
            uint balThisBefore = address(this).balance;
            ret = c.transfer(from, address(this), tos, v);
            assert(ret && address(c).balance == balBefore && address(this).balance == balThisBefore);
        }
    }
    fallback() external payable {}
    receive() external payable {}
}

