contract InvMutTest {
    C c;
    uint callCount;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint v) public payable {
        require(v > 0);
        address[] memory tos = new address[](1);
        tos[0] = to;
        uint before = callCount;
        bool ret = c.transfer(from, address(this), tos, v);
        assert(ret && callCount == before + 1);
    }
    fallback() external payable {
        callCount++;
    }
    receive() external payable {}
