contract InvMutTest {
    C c;
    address lastFrom;
    address lastTo;
    uint lastV;
    address lastCaller;
    uint callCount;
    constructor(C _c) { c = _c; }
    function run(address from, address to, uint v) public payable {
        require(v > 0);
        require(uint160(to) > 0);
        address[] memory tos = new address[](1);
        tos[0] = to;
        callCount = 0;
        bool ret = c.transfer(from, address(this), tos, v);
        assert(ret && callCount == 1 && lastCaller == address(c) && lastFrom == from && lastTo == to && lastV == v);
    }
    fallback() external payable {
        callCount++;
        lastCaller = msg.sender;
        if (msg.data.length >= 100) {
            lastFrom = abi.decode(msg.data[4:36], (address));
            lastTo = abi.decode(msg.data[36:68], (address));
            lastV = abi.decode(msg.data[68:100], (uint256));
        }
    }
    receive() external payable {}
}

